export default async function next({messages,previous,scheduledAt},context){if(!Array.isArray(messages)||messages.length>100)throw Error('Invalid Outlook message page');const seen=await context.state.get('seen-outlook-support-ids');if(seen!==null&&(!Array.isArray(seen)||seen.some(x=>typeof x!=='string')))throw Error('Invalid saved message IDs');let i=previous?.index??0;if(!Number.isInteger(i)||i<0)throw Error('Invalid message index');for(;i<messages.length;i++){const m=messages[i];if(!m||typeof m.id!=='string'||!m.id||!m.body||typeof m.body.content!=='string'||!m.body.content.trim()||typeof m.subject!=='string'||typeof m.from?.emailAddress?.address!=='string')throw Error('Invalid Outlook message');if(!seen?.includes(m.id))return{state:{index:i+1},more:true,messageId:m.id,prompt:`Reported by ${m.from.emailAddress.name??''} <${m.from.emailAddress.address}>
Reported at: ${scheduledAt}
Summary: ${m.subject}
Description:
${m.body.content}`};}return{state:{index:i},more:false,messageId:'',prompt:''};}
